html:
{% set design = frappe.get_doc("Design Master", doc.custom_design_master) if doc.custom_design_master else None %}
{% set sizes = design.size_configuration | selectattr("finished_item_a", "equalto", doc.production_item) | list if design else [] %}
{% set size = sizes[0] if sizes else None %}
{% set recipe = frappe.get_doc("Warp Recipe", size.warp_recipe) if size and size.warp_recipe else None %}
{% set beams = frappe.get_all("Production Beam", filters={"work_order": doc.name, "is_group": 0}, fields=["name", "length_m", "workstation", "planned_pieces"], order_by="creation") %}
<style>.wo td,.wo th{border:1px solid #000;padding:5px 9px;font-size:13px}.wo{border-collapse:collapse;width:100%}</style>
<h3 style="text-align:center">{{ _("Work Order") }} {{ doc.name }}</h3>
<table class="wo">
<tr><td>{{ _("Issue Date") }}</td><td>{{ frappe.format(doc.creation, {"fieldtype": "Date"}) }}</td><td>{{ _("Article Name") }}</td><td>{{ doc.custom_article_name or "" }}</td></tr>
<tr><td>{{ _("PO") }}</td><td>{{ doc.sales_order or "" }}</td><td>{{ _("Size") }}</td><td>{{ size.size_code if size else "" }}</td></tr>
<tr><td>{{ _("Design No.") }}</td><td>{{ doc.custom_design_no or "" }}</td><td>{{ _("Quantity") }}</td><td>{{ doc.qty }}</td></tr>
<tr><td>{{ _("Working Date") }}</td><td>{{ frappe.format(doc.planned_start_date, {"fieldtype": "Datetime"}) if doc.planned_start_date else "" }}</td><td></td><td></td></tr>
</table><br>
<table class="wo"><tr><th>{{ _("No. of beams") }}</th><th>{{ _("Beam length") }}</th><th>{{ _("Loom number") }}</th><th>{{ _("Pieces") }}</th></tr>
{% for beam in beams %}<tr><td>1</td><td>{{ beam.length_m }}</td><td>{{ beam.workstation or "" }}</td><td>{{ beam.planned_pieces }}</td></tr>{% endfor %}
</table><br>
{% if recipe %}<table class="wo"><tr><th>{{ _("Seq") }}</th><th>{{ _("Kind") }}</th><th>{{ _("Count") }}</th><th>{{ _("Color") }}</th><th>{{ _("Ends") }}</th><th>{{ _("Repeat") }}</th><th>{{ _("Total") }}</th></tr>
{% for row in recipe.yarn_items | sort(attribute="sequence") %}<tr><td>{{ row.sequence or loop.index }}</td><td>{{ row.kind or "" }}</td><td>{{ row.yarn_count or row.yarn_item }}</td><td>{{ row.color or "" }}</td><td>{{ row.ends or "" }}</td><td>{{ row.block_repeats or 1 }}</td><td>{{ row.row_total_ends or "" }}</td></tr>{% endfor %}
<tr><th colspan="6">{{ _("Total ends") }}</th><th>{{ recipe.total_ends or "" }}</th></tr>
{% if recipe.missing_ends %}<tr><td colspan="6">{{ _("Missing ends") }}</td><td>{{ recipe.missing_ends }}</td></tr>{% endif %}</table>
{% if recipe.applicable_sizes %}<p>{{ _("Sizes") }}: {{ recipe.applicable_sizes }}</p>{% endif %}{% endif %}
